#!/usr/bin/env bash
# Majorité, étape 4 — tout en ligne, et les 18 ans.
# - Plus de formulaire de droit à l'image pré-rempli (ni pour l'admin, ni pour le membre) : le PDF n'existe
#   qu'une fois les choix validés, par le majeur ou par le parent ;
# - le parent confirme (ou donne) la date de naissance en validant ; elle devient celle de la fiche ;
# - profil : le membre voit toujours sa date ; mineur, il ne la change pas (son parent) ; majeur, il la corrige
#   sans pouvoir redevenir mineur ;
# - chaque nuit : un mineur qui a 18 ans passe majeur, coordonnées du parent effacées, e-mail au jeune ;
#   bandeau « confirmer ou modifier mes choix » tant que ses droits viennent du parent ;
# - doc, guide admin, visite guidée, e2e. Pas de migration.
# Prérequis : apply-majorite-3-fiche-membre.sh.
# Usage (racine du repo) : bash apply-majorite-4-tout-en-ligne.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"packages/backend/src/modules/privacy/retention.service.ts" 2>/dev/null | grep -qF "promoteNewAdults"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "LegalStatusControl" "apps/web/src/app/(admin)/dashboard/users/[id]/page.tsx" 2>/dev/null || { echo "lancez d'abord apply-majorite-3-fiche-membre.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/admin/droit-image-d-un-mineur.mdx" "apps/web/content/docs/dev/legal/consentement-en-ligne.mdx" "apps/web/src/features/admin/users/forms/update-me/UpdateMeForm.tsx" "apps/web/src/features/admin/users/forms/update-me/updateMeForm.action.ts" "apps/web/src/features/admin/users/legal/LegalStatusControl.tsx" "apps/web/src/features/docs/entities/procedureMap.generated.json" "apps/web/src/features/image-consent/GuardianConsentPage.tsx" "apps/web/src/features/image-consent/OnlineConsentForm.tsx" "apps/web/src/features/tours/definitions/admin.users.droit-image-mineur.ts" "e2e/data.mjs" "e2e/droit-a-l-image-parent-pages.spec.ts" "e2e/droit-a-l-image-parent.spec.ts" "e2e/prepare.mjs" "packages/backend/src/email/templates/imageConsentGuardian.ts" "packages/backend/src/modules/imageConsent/imageConsentGuardian.service.ts" "packages/backend/src/modules/imageConsent/imageConsentOnline.service.ts" "packages/backend/src/modules/imageConsent/router.ts" "packages/backend/src/modules/privacy/retention.service.ts" "packages/contracts/src/legal/imageConsent.ts" "apps/web/src/app/api/media/image-consent/prefilled/route.ts")
CREATED=("e2e/dix-huit-ans.spec.ts" "packages/backend/src/email/templates/comingOfAge.ts" "packages/backend/src/modules/users/comingOfAge.service.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "promoteNewAdults" "packages/backend/src/modules/privacy/retention.service.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

